//! EC register layouts of MSI laptops, keyed by EC firmware version.
//!
//! The table comes from the Linux [msi-ec](https://github.com/BeardOverflow/msi-ec) driver, which
//! groups firmware versions into configs (`CONF_*`) that share one register layout. `msi_ec.rs` is
//! generated by `tools/gen-models.py`; regenerate it rather than editing it by hand.
//!
//! Registers msi-ec marks as unknown or unsupported are `None`. The values are msi-ec's and are not
//! confirmed on hardware by this project.

mod msi_ec;

use msi_ec::CONFS;

/// One bit of an EC register; msi-ec treats a set bit as "on".
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Bit {
    pub address: u8,
    pub bit: u8,
}

/// One bit of an EC register whose meaning some firmware flips.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InvertibleBit {
    pub address: u8,
    pub bit: u8,
    pub invert: bool,
}

/// Named register values, names exactly as msi-ec ("eco", "comfort", "sport", "turbo", "auto",
/// "silent", "basic", "advanced", ...).
///
/// msi-ec writes a value as the whole register byte and recognises the current mode only when the
/// register equals one of the values exactly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Modes {
    pub address: u8,
    pub modes: &'static [(&'static str, u8)],
}

/// A switch that is on while all `mask` bits are set; msi-ec sets or clears only those bits.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Masked {
    pub address: u8,
    pub mask: u8,
}

/// Read-only sensor registers of one CPU or GPU.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Sensors {
    /// Current temperature, °C.
    pub rt_temp: Option<u8>,
    /// Current fan speed, percent of maximum.
    pub rt_fan_speed: Option<u8>,
}

/// Mute and mic-mute LEDs: bit `bit` of each register, set = LED on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Leds {
    pub micmute: Option<u8>,
    pub mute: Option<u8>,
    pub bit: u8,
}

/// Keyboard backlight.
///
/// msi-ec writes `state_base | level` (level `0..=max_state`) to `state_address` and reads the level
/// back from the low two bits. The mode register and its values are defined by msi-ec but not used
/// by it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KbdBacklight {
    pub mode_address: Option<u8>,
    pub modes: &'static [u8],
    pub max_mode: u8,
    pub state_address: Option<u8>,
    pub state_base: u8,
    pub max_state: u8,
}

/// The EC register layout of one msi-ec config.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ModelConf {
    /// msi-ec config name, e.g. "CONF_G2_1".
    pub name: &'static str,
    /// EC firmware strings this config applies to, e.g. "15K1IMS1.113".
    pub firmware: &'static [&'static str],
    /// Stop-charge register; value = 0x80 | percent.
    pub charge_control: Option<u8>,
    /// Set = webcam on.
    pub webcam: Option<Bit>,
    /// msi-ec reports the webcam as blocked while this bit is clear.
    pub webcam_block: Option<Bit>,
    /// msi-ec reports the Win key on the left when the bit XOR `invert` is 1.
    pub fn_win_swap: Option<InvertibleBit>,
    /// Set = fans at maximum.
    pub cooler_boost: Option<Bit>,
    pub shift_mode: Option<Modes>,
    pub super_battery: Option<Masked>,
    pub fan_mode: Option<Modes>,
    pub cpu: Sensors,
    pub gpu: Sensors,
    pub leds: Option<Leds>,
    pub kbd_backlight: Option<KbdBacklight>,
}

/// Config whose firmware list contains `firmware` exactly.
pub fn lookup(firmware: &str) -> Option<&'static ModelConf> {
    CONFS.iter().find(|conf| conf.firmware.contains(&firmware))
}

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use super::*;

    #[test]
    fn cyborg_15_firmware_has_the_ms_15k1_registers() {
        let conf = lookup("15K1IMS1.113").expect("15K1IMS1.113 is listed by msi-ec");

        let shift = conf.shift_mode.expect("shift mode");
        assert_eq!(shift.address, 0xD2);
        for mode in [("turbo", 0xC4), ("eco", 0xC2), ("comfort", 0xC1)] {
            assert!(shift.modes.contains(&mode), "shift mode {mode:?} missing from {:?}", shift.modes);
        }

        let fan = conf.fan_mode.expect("fan mode");
        assert_eq!(fan.address, 0xD4);
        for mode in [("auto", 0x0D), ("silent", 0x1D), ("advanced", 0x8D)] {
            assert!(fan.modes.contains(&mode), "fan mode {mode:?} missing from {:?}", fan.modes);
        }

        assert_eq!(conf.cooler_boost, Some(Bit { address: 0x98, bit: 7 }));
        assert_eq!(conf.charge_control, Some(0xD7));
        assert_eq!(conf.fn_win_swap, Some(InvertibleBit { address: 0xE8, bit: 4, invert: true }));
        assert_eq!(conf.webcam, Some(Bit { address: 0x2E, bit: 1 }));
        assert_eq!(conf.cpu.rt_temp, Some(0x68));
    }

    #[test]
    fn every_firmware_belongs_to_exactly_one_config() {
        let mut owners: HashMap<&str, &str> = HashMap::new();
        for conf in CONFS {
            assert!(!conf.firmware.is_empty(), "{} lists no firmware", conf.name);
            for &firmware in conf.firmware {
                if let Some(first) = owners.insert(firmware, conf.name) {
                    panic!("{firmware} is listed by both {first} and {}", conf.name);
                }
            }
        }
    }

    #[test]
    fn unknown_or_partial_firmware_has_no_config() {
        for firmware in ["", "NOTAFW00.000", "15K1IMS1", "15K1IMS1.113 ", "15k1ims1.113"] {
            assert_eq!(lookup(firmware), None, "{firmware:?} must not match");
        }
    }
}
